+      ["name", call.name],
+      ["kind", call.kind],
+      ["path", relativePath(call.path)],
+      ["resolved", call.resolved ? null : "false"],
+    ]));
+  }
+
+  for (const diagnostic of result.diagnostics ?? []) {
+    lines.push(llmLine("diagnostic", [
+      ["code", diagnostic.code],
+      ["message", diagnostic.message],
+    ]));
+  }
+
+  return lines;
+}

