+
+  for (const note of rendered.notes) {
+    lines.push(llmLine("note", [["text", note]]));
+  }
+
+  for (const diagnostic of facts.diagnostics) {
+    lines.push(llmLine("diagnostic", [
+      ["code", diagnostic.code],
+      ["message", diagnostic.message],
+    ]));
+  }
